function ExpectedCoverTime(B, n):
  m <- |B|;  total <- 0
  for each nonempty subset S of {0..n-1}:
     c <- number of blocks b in B with b ∩ S ≠ ∅
     total <- total + (-1)^(|S|+1) * m / c        # exact rational
  return total

function UniformCoverTime(n, k):
  M <- C(n,k);  total <- 0
  for s in 1..n:
     c <- M - C(n-s, k)
     if c > 0: total <- total + (-1)^(s+1) * C(n,s) * M / c
  return total

function ProjectiveLines(q):
  pts <- normalized nonzero vectors of GF(q)^3
  for each dual point (a,b,c) in pts:
     line <- { index(p) : a*p1+b*p2+c*p3 ≡ 0 (mod q) }
  return distinct lines, |pts|

